20	/**
21	 * Parse and decode geo json
22	 */
23	
24	import * as zrUtil from 'zrender/src/core/util';
25	import { GeoJSONLineStringGeometry, GeoJSONPolygonGeometry, GeoJSONRegion } from './Region';
26	import { GeoJSONCompressed, GeoJSON } from './geoTypes';
27	
28	
29	function decode(json: GeoJSONCompressed | GeoJSON): GeoJSON {
30	    if (!(json as GeoJSONCompressed).UTF8Encoding) {
31	        return json as GeoJSON;
32	    }
33	    const jsonCompressed = json as GeoJSONCompressed;
34	    let encodeScale = jsonCompressed.UTF8Scale;
35	    if (encodeScale == null) {
36	        encodeScale = 1024;
37	    }
38	
39	    const features = jsonCompressed.features;
40	    zrUtil.each(features, feature => {
41	        const geometry = feature.geometry;
42	        const encodeOffsets = geometry.encodeOffsets;
43	        const coordinates = geometry.coordinates;
44	
45	        // Geometry may be appeded manually in the script after json loaded.
46	        // In this case this geometry is usually not encoded.
47	        if (!encodeOffsets) {
48	            return;
49	        }
50	
51	        switch (geometry.type) {
52	            case 'LineString':
53	                (geometry as any).coordinates =
54	                    decodeRing(coordinates as string, encodeOffsets as number[], encodeScale);
55	                break;
56	            case 'Polygon':
57	                decodeRings(coordinates as string[], encodeOffsets as number[][], encodeScale);
58	                break;
59	            case 'MultiLineString':
60	                decodeRings(coordinates as string[], encodeOffsets as number[][], encodeScale);
61	                break;
62	            case 'MultiPolygon':
63	                zrUtil.each(
64	                    coordinates as string[][],
65	                    (rings, idx) => decodeRings(rings, (encodeOffsets as number[][][])[idx], encodeScale)
66	                );
67	        }
68	    });
69	    // Has been decoded
70	    jsonCompressed.UTF8Encoding = false;
71	
72	    return jsonCompressed as unknown as GeoJSON;
73	}
74	
75	function decodeRings(
76	    rings: string[],
77	    encodeOffsets: number[][],
78	    encodeScale: number
79	) {
80	    for (let c = 0; c < rings.length; c++) {
81	        rings[c] = decodeRing(
82	            rings[c],
83	            encodeOffsets[c],
84	            encodeScale
85	        ) as any;
86	    }
87	}
88	
89	function decodeRing(
90	    coordinate: string,
91	    encodeOffsets: number[],
92	    encodeScale: number
93	): number[][] {
94	    const result = [];
95	    let prevX = encodeOffsets[0];
96	    let prevY = encodeOffsets[1];
97	
98	    for (let i = 0; i < coordinate.length; i += 2) {
99	        let x = coordinate.charCodeAt(i) - 64;
100	        let y = coordinate.charCodeAt(i + 1) - 64;
101	        // ZigZag decoding
102	        x = (x >> 1) ^ (-(x & 1));
103	        y = (y >> 1) ^ (-(y & 1));
104	        // Delta deocding
105	        x += prevX;
106	        y += prevY;
107	
108	        prevX = x;
109	        prevY = y;
110	        // Dequantize
111	        result.push([x / encodeScale, y / encodeScale]);
112	    }
113	
114	    return result;
115	}
116	
117	export default function parseGeoJSON(geoJson: GeoJSON | GeoJSONCompressed, nameProperty: string): GeoJSONRegion[] {
118	
119	    geoJson = decode(geoJson);
120	
121	    return zrUtil.map(zrUtil.filter(geoJson.features, function (featureObj) {
122	        // Output of mapshaper may have geometry null
123	        return featureObj.geometry
124	            && featureObj.properties
125	            && featureObj.geometry.coordinates.length > 0;
126	    }), function (featureObj) {
127	        const properties = featureObj.properties;
128	        const geo = featureObj.geometry;
129	
130	        const geometries = [] as GeoJSONRegion['geometries'];
131	        switch (geo.type) {
132	            case 'Polygon':
133	                const coordinates = geo.coordinates;
134	                // According to the GeoJSON specification.
135	                // First must be exterior, and the rest are all interior(holes).
136	                geometries.push(new GeoJSONPolygonGeometry(coordinates[0], coordinates.slice(1)));
137	                break;
138	            case 'MultiPolygon':
139	                zrUtil.each(geo.coordinates, function (item) {
140	                    if (item[0]) {
141	                        geometries.push(new GeoJSONPolygonGeometry(item[0], item.slice(1)));
142	                    }
143	                });
144	                break;
145	            case 'LineString':
146	                geometries.push(new GeoJSONLineStringGeometry([geo.coordinates]));
147	                break;
148	            case 'MultiLineString':
149	                geometries.push(new GeoJSONLineStringGeometry(geo.coordinates));
150	
151	        }
152	
153	        const region = new GeoJSONRegion(
154	            properties[nameProperty || 'name'],
155	            geometries,
156	            properties.cp
157	        );
158	        region.properties = properties;
159	        return region;
160	    });
161	}

